const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Sistan-Baluchestan region (approximate bounding box)
  const geometry = ee.Geometry.Rectangle([59.5, 29.5, 63.5, 32.5]);

  // Date range: January 8-15, 2020
  const startDate = '2020-01-08';
  const endDate = '2020-01-15';

  // Load CHIRPS daily precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  // Check if data exists
  const imgCount = chirps.size().getInfo();
  print(`CHIRPS Images in date range: ${imgCount}`);

  if (imgCount === 0) {
    print('No CHIRPS data found for date range.');
    print('C1');
    return;
  }

  // Sum precipitation over the date range (daily CHIRPS values)
  const totalPrecip = chirps.select('precipitation').sum();

  // Calculate mean precipitation over the region (in mm)
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const precipMm = stats.precipitation;
  print(`Total Precip (mm): ${precipMm !== null ? precipMm.toFixed(2) : 'null'}`);

  // Validate result
  if (precipMm === null || isNaN(precipMm)) {
    print('C3');
    return;
  }

  // Convert to inches (1 inch = 25.4 mm)
  const precipInches = precipMm / 25.4;
  print(`Total Precip (inches): ${precipInches.toFixed(2)}`);

  // Determine answer
  if (precipInches > 3) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
